/* invention-data.js — entries of the Invention Atlas (invention-atlas.html). */
(function () {
  const I = (i, extra) => ['inv', Object.assign({ i }, extra || {})];
  const E = (ch) => ['e', ch];
  window.INVENTION_CATS = {
    tools: ['Tools & making', '#8a6a4a', '🔨'],
    farm: ['Farming & food', '#6f8a2e', '🌾'],
    energy: ['Energy & power', '#e67e22', '⚡'],
    transport: ['Transport', '#c0392b', '🚗'],
    comm: ['Communication', '#2a8fa3', '📡'],
    compute: ['Numbers & computing', '#3e8ec4', '💻'],
    science: ['Science instruments', '#8a6cc0', '🔭'],
    home: ['Home & everyday life', '#c2185b', '🏠'],
    material: ['Materials & building', '#45525e', '🧱']
  };
  window.INVENTION_ERAS = [
    { n: 'Stone Age', to: -3300, range: '3.3 million years ago – 3300 BCE', intro: 'Stone tools, fire, clothing, pottery and farming — the inventions that made us human and let us settle down.' },
    { n: 'Ancient world', to: 500, range: '3300 BCE – 500 CE', intro: 'Cities brought writing, the wheel, metals, money, roads, aqueducts and concrete. China, India, Mesopotamia, Egypt, Greece and Rome all added inventions.' },
    { n: 'Middle Ages', to: 1450, range: '500 – 1450', intro: 'Paper, printing, the compass and gunpowder came from China; zero from India; windmills, clocks and glasses spread across the Islamic world and Europe.' },
    { n: 'Age of discovery & science', to: 1760, range: '1450 – 1760', intro: 'The printing press spread knowledge fast. Telescopes, microscopes, thermometers and calculators helped the scientific revolution, and the first steam engines pumped mines.' },
    { n: 'Industrial Revolution', to: 1870, range: '1760 – 1869', intro: 'Steam power, factories, railways and the telegraph changed how people worked, travelled and talked.' },
    { n: 'Age of electricity', to: 1945, range: '1870 – 1944', intro: 'Electric light, telephones, radio, cars, aeroplanes, plastics and the first computers transformed daily life.' },
    { n: 'Electronic age', to: 1990, range: '1945 – 1989', intro: 'Transistors and chips made electronics small and cheap: TV, satellites, personal computers, mobile phones and the internet.' },
    { n: 'Digital age', to: 99999, range: '1990 – today', intro: 'The web, smartphones, lithium batteries, cheap solar power and artificial intelligence connect and change the world.' }
  ];
  window.INVENTIONS = [
    // ---------------- Stone Age
    { id: 'stone-tools', n: 'Stone tools', c: 'tools', y: -3300000, d: 'c. 3.3 million years ago', r: 'Kenya (Lomekwi)', w: 'Early human ancestors', s: 'Sharp flakes knocked from stones — the first technology, older than our own species.', how: 'Striking one stone with another breaks off a flake with a razor-sharp edge.', impact: 'Cutting meat and plants gave our ancestors more food, perhaps helping bigger brains evolve.', f: 'The oldest known stone tools are older than the genus Homo.', p: ['chopper'], x: ['fire', ['weapons-atlas.html#hand-axe', 'The hand axe']] },
    { id: 'fire', n: 'Control of fire', c: 'energy', y: -1000000, d: 'c. 1 million years ago', r: 'Africa (Wonderwerk Cave, South Africa)', w: 'Homo erectus', s: 'Keeping and later making fire gave warmth, light, protection and cooked food.', how: 'Early humans kept natural fires going; later they made fire by friction or striking flint on pyrite.', impact: 'Cooking made food easier to digest, and fire let people live in cold places.', f: 'Burned bones and ash a million years old were found deep in Wonderwerk Cave.', p: I('fire'), x: ['stone-tools', 'pottery'] },
    { id: 'needle', n: 'Sewing needle', c: 'tools', y: -48000, d: 'c. 50,000 years ago', r: 'Siberia (Denisova Cave), later worldwide', w: 'Denisovans and early modern humans', s: 'Bone needles with an eye let people sew fitted, warm clothes from skins.', how: 'A sharp point pierces the skin; the eye pulls a thread of sinew through.', impact: 'Fitted clothing helped humans survive Ice Age winters in the far north.', f: 'The Denisova Cave needle is made from a bird bone.', p: I('needle'), x: ['sewing-machine'] },
    { id: 'pottery', n: 'Pottery', c: 'home', y: -18000, d: 'c. 20,000 years ago', r: 'China (Xianrendong Cave)', w: 'Stone Age hunter-gatherers', s: 'Clay shaped into pots and hardened in fire, for cooking and storing food.', how: 'Heating clay above about 600 °C changes it into hard, waterproof ceramic.', impact: 'Pots made cooking soups and storing grain possible.', f: 'The oldest pots were made by hunter-gatherers, long before farming.', p: I('pottery'), x: ['farming', 'glass'] },
    { id: 'farming', n: 'Farming', c: 'farm', y: -9500, d: 'c. 9500 BCE', r: 'Fertile Crescent; separately in China, the Americas, Africa and New Guinea', w: 'Neolithic farmers', s: 'Planting seeds and taming animals, instead of only gathering and hunting.', how: 'People chose and replanted the best seeds of wild wheat, barley, rice and maize until crops changed.', impact: 'Farming fed villages, then cities — and led to writing, kings and armies.', f: 'Farming was invented separately in at least seven places.', p: I('farm'), x: ['plough', 'pottery'] },
    { id: 'smelting', n: 'Metal smelting', c: 'material', y: -5000, d: 'c. 5000 BCE', r: 'Serbia (Belovode) and the Near East', w: 'Copper Age metalworkers', s: 'Heating rock (ore) with charcoal to get metal out of it, starting with copper.', how: 'Hot charcoal takes the oxygen out of copper ore, leaving liquid metal.', impact: 'Metal tools and weapons replaced stone. Bronze (copper and tin) came next, then iron.', f: 'Ötzi the Iceman (c. 3300 BCE) carried a copper axe.', p: I('bronze'), x: ['iron', ['weapons-atlas.html#copper-axe', 'Copper axe']] },
    { id: 'plough', n: 'Plough', c: 'farm', y: -4000, d: 'c. 4000 BCE', r: 'Mesopotamia', w: 'Early farmers', s: 'A blade pulled through the soil to break it up for planting, at first by people, then by oxen.', how: 'A pointed wooden ard scratches a furrow; later ploughs turned the soil over.', impact: 'Farmers could plant far more land, growing extra food for cities.', f: 'Plough marks over 5,000 years old have been found in Europe.', p: I('plough'), x: ['farming', 'seed-drill'] },
    { id: 'sailboat', n: 'Sailboat', c: 'transport', y: -3500, d: 'c. 3500 BCE', r: 'Egypt and Mesopotamia', w: 'Nile and Gulf sailors', s: 'A sail catches the wind to push a boat — the first use of wind power.', how: 'Wind pushes on the cloth; later sails could even sail against the wind at an angle.', impact: 'Trade, exploration and empires spread by sea.', f: 'Polynesian navigators reached islands across the Pacific by reading stars, waves and birds.', p: I('sail'), x: ['compass', ['weapons-atlas.html#trireme', 'Trireme']] },
    // ---------------- ancient
    { id: 'wheel', n: 'Wheel', c: 'transport', y: -3500, d: 'c. 3500 BCE', r: 'Mesopotamia and Eastern Europe', w: 'Unknown inventors', s: 'A round disc turning on an axle. Potters used it before carts.', how: 'A wheel rolls instead of dragging, so friction is far lower.', impact: 'Carts, chariots, mills, gears and almost every machine depend on it.', f: 'The oldest wooden wheel found, in Slovenia, is about 5,150 years old.', p: I('solidwheel'), x: ['chariot-wheel', ['weapons-atlas.html#chariot', 'The war chariot']] },
    { id: 'writing', n: 'Writing', c: 'comm', y: -3200, d: 'c. 3200 BCE', r: 'Mesopotamia (Sumer); separately in Egypt, China and Mesoamerica', w: 'Sumerian scribes', s: 'Marks pressed into clay to record words. Cuneiform began as records of grain and animals.', how: 'Pictures became signs for sounds and ideas, pressed into wet clay with a reed.', impact: 'Laws, history, science and stories could be kept and shared.', f: 'Some of the oldest writing is receipts and tax records.', p: I('writing'), x: ['alphabet', 'paper'] },
    { id: 'glass', n: 'Glass', c: 'material', y: -2500, d: 'c. 2500 BCE', r: 'Mesopotamia', w: 'Mesopotamian craftworkers', s: 'Sand melted with soda and lime becomes clear or coloured glass.', how: 'Very hot sand melts; cooling it fast stops crystals forming, leaving glass.', impact: 'Beads, then bottles, windows, lenses, telescopes and screens.', f: 'Glassblowing was invented around 50 BCE in Syria.', p: I('glass'), x: ['eyeglasses', 'telescope'] },
    { id: 'alphabet', n: 'Alphabet', c: 'comm', y: -1850, d: 'c. 1850 BCE', r: 'Sinai and Egypt', w: 'Canaanite workers', s: 'A few dozen letters standing for sounds, instead of hundreds of signs for words.', how: 'Each sign stands for one consonant; Greeks later added vowels.', impact: 'Writing became easy to learn. Most alphabets in the world come from this one.', f: 'The letter A began as a picture of an ox’s head (aleph).', p: I('alphabet'), x: ['writing', 'printing-press'] },
    { id: 'chariot-wheel', n: 'Spoked wheel', c: 'transport', y: -2000, d: 'c. 2000 BCE', r: 'Russian steppes', w: 'Sintashta culture', s: 'Wheels with spokes instead of solid wood — far lighter and faster.', how: 'Spokes carry the load from the rim to the hub with much less wood.', impact: 'Fast chariots, then carts and carriages, and later bicycles.', f: 'Bicycle wheels use thin wire spokes under tension — the same idea, improved.', p: I('wheel'), x: ['wheel', 'bicycle'] },
    { id: 'iron', n: 'Iron working', c: 'material', y: -1200, d: 'c. 1200 BCE', r: 'Anatolia and the Near East; separately in West Africa', w: 'Hittite and other smiths', s: 'Iron ore is common, so once people learned to work it, iron tools became cheap.', how: 'Iron was heated in a furnace and hammered; adding carbon made steel.', impact: 'Iron ploughs, axes and nails helped farming and building spread.', f: 'Ironworking in West Africa (Nok culture) began at least 2,500 years ago.', p: I('iron'), x: ['smelting', 'bessemer-steel'] },
    { id: 'coins', n: 'Coins', c: 'home', y: -600, d: 'c. 600 BCE', r: 'Lydia (Turkey); also China', w: 'Lydian kings', s: 'Small metal pieces of fixed weight, stamped by the ruler to guarantee their value.', how: 'A stamp showed who made the coin, so people trusted it without weighing.', impact: 'Trade became easier; coins spread across the ancient world.', f: 'The first coins were made of electrum, a natural mix of gold and silver.', p: I('coin'), x: ['paper-money'] },
    { id: 'crane', n: 'Crane', c: 'material', y: -515, d: 'c. 515 BCE', r: 'Greece', w: 'Greek builders', s: 'A machine with pulleys and a winch to lift heavy stones.', how: 'Pulleys share the load among several ropes, so a small force can lift a big weight.', impact: 'Builders could use bigger stones with fewer workers. Romans used treadwheel cranes.', f: 'Roman treadwheel cranes were powered by people walking inside a giant wheel.', p: I('crane'), x: ['screw'] },
    { id: 'abacus', n: 'Abacus', c: 'compute', y: -500, d: 'by c. 500 BCE (counting boards)', r: 'Mesopotamia, Greece, Rome and China', w: 'Traders and clerks', s: 'Beads or pebbles moved on rods or lines to add, subtract, multiply and divide quickly.', how: 'Each row stands for ones, tens, hundreds and so on.', impact: 'Used for 2,500 years; still taught in some schools for mental arithmetic.', f: 'The word “calculate” comes from calculus, Latin for pebble.', p: I('abacus'), x: ['zero', 'pascaline'] },
    { id: 'aqueduct', n: 'Aqueduct', c: 'material', y: -312, d: '312 BCE', r: 'Rome', w: 'Appius Claudius Caecus (Aqua Appia)', s: 'Channels that carried water by gravity from hills to cities, sometimes over high arched bridges.', how: 'A very gentle downward slope over many kilometres kept water flowing.', impact: 'Rome had about 11 aqueducts, supplying fountains, baths and homes.', f: 'The Pont du Gard in France drops only 2.5 cm in 456 metres.', p: I('aqueduct'), x: ['concrete'] },
    { id: 'lighthouse', n: 'Lighthouse', c: 'transport', y: -280, d: 'c. 280 BCE', r: 'Alexandria, Egypt', w: 'Sostratus of Cnidus', s: 'A tall tower with a fire on top to guide ships into harbour.', how: 'A fire, and later lamps with mirrors and lenses, shone far out to sea.', impact: 'Safer sea travel; one of the Seven Wonders of the Ancient World.', f: 'The Pharos of Alexandria stood for over 1,500 years before earthquakes destroyed it.', p: I('lighthouse'), x: ['sailboat'] },
    { id: 'screw', n: 'Archimedes’ screw', c: 'tools', y: -250, d: 'c. 250 BCE', r: 'Syracuse (Sicily) or Egypt', w: 'Archimedes (traditionally)', s: 'A spiral inside a tube that lifts water when turned.', how: 'Turning the screw carries pockets of water upward along the spiral.', impact: 'Used for irrigation for over 2,000 years; similar screws pump water today.', f: 'Archimedes also explained levers: “Give me a place to stand and I will move the Earth.”', p: I('screw'), x: ['waterwheel'] },
    { id: 'waterwheel', n: 'Water wheel', c: 'energy', y: -250, d: 'c. 3rd century BCE', r: 'Greece; also China', w: 'Philo of Byzantium described it', s: 'A wheel turned by flowing water to grind grain or power hammers and saws.', how: 'Water pushes on paddles or fills buckets, turning the wheel and its axle.', impact: 'The main source of factory power until steam engines.', f: 'England’s Domesday Book of 1086 lists about 6,000 watermills.', p: I('waterwheel'), x: ['windmill', 'steam-engine'] },
    { id: 'concrete', n: 'Roman concrete', c: 'material', y: -200, d: 'c. 2nd century BCE', r: 'Rome', w: 'Roman builders', s: 'Lime, volcanic ash and rubble mixed with water set into strong artificial stone.', how: 'Volcanic ash reacts with lime to form minerals that keep strengthening over time.', impact: 'Domes, harbours and aqueducts. The Pantheon’s concrete dome (c. 125 CE) still stands.', f: 'Roman sea walls get stronger in seawater; modern concrete often crumbles.', p: I('dome'), x: ['aqueduct', 'skyscraper'] },
    { id: 'antikythera', n: 'Antikythera mechanism', c: 'compute', y: -100, d: 'c. 100 BCE', r: 'Greece', w: 'Unknown Greek engineers', s: 'A box of bronze gears that calculated the positions of the Sun, Moon and planets — the oldest known analogue computer.', how: 'Turning a handle moved at least 30 gears, showing dates, eclipses and the Olympic Games.', impact: 'Nothing as complex is known again until medieval clocks 1,400 years later.', f: 'It was found in a shipwreck in 1901; X-ray scans revealed its secrets.', p: I('antikythera'), x: ['mechanical-clock', 'abacus'] },
    { id: 'paper', n: 'Paper', c: 'comm', y: 105, d: '105 CE', r: 'China', w: 'Cai Lun (earlier forms existed)', s: 'Sheets made from mashed plant fibres — cheaper and lighter than silk, bamboo or parchment.', how: 'Bark, rags and hemp were soaked and beaten into pulp, spread on a screen and dried.', impact: 'Paper spread to the Islamic world (751) and Europe, making books and printing cheap.', f: 'Paper-making reached Samarkand after Chinese papermakers were captured at the Battle of Talas.', p: I('scroll'), x: ['writing', 'woodblock-printing'] },
    { id: 'wheelbarrow', n: 'Wheelbarrow', c: 'tools', y: 100, d: '1st–2nd century CE', r: 'China', w: 'Chinese engineers (legend credits Zhuge Liang)', s: 'A single wheel and two handles let one person move heavy loads.', how: 'The wheel takes most of the weight, acting as a lever.', impact: 'Used on farms and building sites; Chinese armies used them to carry supplies.', f: 'Chinese wheelbarrows sometimes had sails.', p: E('🛒'), x: ['wheel'] },
    { id: 'seismograph', n: 'Earthquake detector', c: 'science', y: 132, d: '132 CE', r: 'China', w: 'Zhang Heng', s: 'A bronze jar with eight dragons that dropped a ball to show the direction of a distant earthquake.', how: 'A pendulum inside swung when the ground shook, knocking a ball from one dragon into a toad’s mouth.', impact: 'Modern seismographs record earthquakes and help warn of tsunamis.', f: 'It once detected an earthquake hundreds of kilometres away that no one in the capital had felt.', p: E('🐉'), x: ['antikythera'] },
    // ---------------- Middle Ages
    { id: 'zero', n: 'Zero and place-value numbers', c: 'compute', y: 628, d: '628', r: 'India', w: 'Brahmagupta', s: 'Zero as a real number, and digits whose value depends on their place — the numbers we use today.', how: 'In 305, the 3 means 3 hundreds and the 0 holds the tens place empty.', impact: 'Spread through the Islamic world (al-Khwarizmi) to Europe as “Arabic numerals”, making maths far easier.', f: 'The word “algorithm” comes from al-Khwarizmi’s name.', p: E('0️⃣'), x: ['abacus', 'computer'] },
    { id: 'windmill', n: 'Windmill', c: 'energy', y: 644, d: 'c. 644', r: 'Persia (Iran)', w: 'Persian millers', s: 'Sails turned by the wind to grind grain and pump water.', how: 'Wind pushes on the sails, turning a shaft that drives millstones.', impact: 'Windmills drained the Netherlands and ground grain across Europe. Wind turbines are their descendants.', f: 'Persian windmills turned on a vertical axis, like a revolving door.', p: I('windmill'), x: ['waterwheel', 'solar-cell'] },
    { id: 'woodblock-printing', n: 'Woodblock printing', c: 'comm', y: 868, d: '868 (oldest dated book)', r: 'China', w: 'Unknown printers', s: 'A whole page carved into a wooden block, inked and pressed onto paper.', how: 'Raised parts of the block take ink and print; cut-away parts stay white.', impact: 'Books became cheaper; the Diamond Sutra of 868 is the oldest dated printed book.', f: 'The Diamond Sutra was found in a sealed cave at Dunhuang in 1900.', p: I('scroll'), x: ['movable-type', 'paper'] },
    { id: 'gunpowder', n: 'Gunpowder', c: 'material', y: 850, d: 'c. 850', r: 'China', w: 'Chinese alchemists', s: 'A mixture of saltpetre, charcoal and sulfur that burns very fast — used for fireworks, mining and weapons.', how: 'Saltpetre supplies oxygen, so the mixture burns rapidly even when enclosed.', impact: 'It changed warfare and later helped mining and building tunnels.', f: 'Chinese fireworks were used at festivals for centuries before guns.', p: E('🎆'), x: ['dynamite', ['weapons-atlas.html#gunpowder', 'Gunpowder in the Weapons Atlas']] },
    { id: 'spinning-wheel', n: 'Spinning wheel', c: 'tools', y: 1000, d: 'c. 1000', r: 'India or the Islamic world', w: 'Unknown spinners', s: 'A wheel that spins thread much faster than a hand spindle.', how: 'Turning a big wheel spins a small spindle fast, twisting fibres into thread.', impact: 'Cloth became cheaper. Gandhi made the spinning wheel a symbol of Indian independence.', f: 'Gandhi’s spinning wheel (charkha) appeared on an early design of India’s flag.', p: I('spinning'), x: ['spinning-jenny', 'needle'] },
    { id: 'paper-money', n: 'Paper money', c: 'home', y: 1024, d: '1024', r: 'China (Song dynasty)', w: 'Song government (jiaozi)', s: 'Printed notes that stood for coins, lighter to carry in large amounts.', how: 'Notes were backed by the government’s promise to exchange them for coins.', impact: 'Marco Polo was amazed by it; Europe adopted banknotes from the 1600s.', f: 'Printing too much money caused some of the first inflation crises in history.', p: E('💵'), x: ['coins', 'credit-card'] },
    { id: 'movable-type', n: 'Movable type', c: 'comm', y: 1040, d: 'c. 1040', r: 'China; metal type in Korea (1377)', w: 'Bi Sheng; Korean printers (Jikji, 1377)', s: 'Single characters made as separate pieces that could be arranged and reused for any page.', how: 'Clay, then metal characters were set in a frame, inked and pressed.', impact: 'The Korean Jikji (1377) is the oldest surviving book printed with metal type.', f: 'Chinese needs thousands of characters, which made movable type harder than in alphabets.', p: I('type'), x: ['woodblock-printing', 'printing-press'] },
    { id: 'compass', n: 'Magnetic compass', c: 'transport', y: 1088, d: '1088 (first clear description)', r: 'China', w: 'Described by Shen Kuo', s: 'A magnetised needle that points north, letting sailors find their way when they cannot see the stars.', how: 'The needle lines up with the Earth’s magnetic field.', impact: 'It made long ocean voyages possible and spread to the Islamic world and Europe by about 1200.', f: 'Shen Kuo also noticed that the compass does not point exactly to true north.', p: I('compass'), x: ['sailboat', 'gps-navigation'] },
    { id: 'mechanical-clock', n: 'Mechanical clock', c: 'science', y: 1283, d: 'c. 1283', r: 'England and Italy (after Su Song’s water clock in China, 1088)', w: 'Unknown monastery clockmakers', s: 'A falling weight drives gears; an escapement lets them move in steady ticks.', how: 'The escapement stops and releases the gears at a regular rate.', impact: 'Towns organised life by the clock; accurate time later allowed navigation at sea.', f: 'Su Song’s astronomical clock tower in China (1088) was 12 metres tall.', p: I('clock'), x: ['pendulum-clock', 'antikythera'] },
    { id: 'eyeglasses', n: 'Eyeglasses', c: 'home', y: 1286, d: 'c. 1286', r: 'Pisa, Italy', w: 'Unknown Italian glassmakers', s: 'Lenses in a frame that help people see clearly.', how: 'Curved glass bends light so it focuses properly on the retina.', impact: 'Scholars and craftspeople could keep working into old age.', f: 'Early glasses were held on the nose or in the hand — arms over the ears came about 1730.', p: I('lens'), x: ['telescope', 'microscope'] },
    { id: 'printing-press', n: 'Printing press', c: 'comm', y: 1440, d: 'c. 1440', r: 'Mainz, Germany', w: 'Johannes Gutenberg', s: 'Metal letters cast in moulds, oil-based ink and a screw press — books could be made in thousands.', how: 'Letters are set in a frame, inked and pressed onto paper with a screw press, like one used for wine.', impact: 'Books, newspapers and ideas spread quickly, helping the Reformation and the scientific revolution.', f: 'About 180 Gutenberg Bibles were printed; 49 survive.', p: I('press'), x: ['movable-type', 'newspaper'] },
    // ---------------- 1450–1760
    { id: 'microscope', n: 'Microscope', c: 'science', y: 1590, d: 'c. 1590', r: 'Netherlands', w: 'Zacharias and Hans Janssen; later Antonie van Leeuwenhoek and Robert Hooke', s: 'Lenses that make tiny things look large.', how: 'One lens makes a magnified image; a second lens magnifies it again.', impact: 'It revealed cells, bacteria and blood cells and led to germ theory.', f: 'Robert Hooke named “cells” after the little rooms of monks, seeing them in cork.', p: I('lens'), x: ['telescope', ['medicine-atlas.html#leeuwenhoek', 'Leeuwenhoek']] },
    { id: 'flush-toilet', n: 'Flush toilet', c: 'home', y: 1596, d: '1596', r: 'England', w: 'John Harington; S-bend by Alexander Cumming (1775)', s: 'A toilet that washes waste away with water.', how: 'Cumming’s S-shaped pipe holds water that blocks smells coming back.', impact: 'With sewers, flush toilets helped end cholera in cities.', f: 'Harington built one for his godmother, Queen Elizabeth I.', p: I('toilet'), x: [['medicine-atlas.html#sewers', 'Sewers']] },
    { id: 'thermometer', n: 'Thermometer', c: 'science', y: 1593, d: '1593; mercury thermometer 1714', r: 'Italy, then Netherlands', w: 'Galileo Galilei; Daniel Fahrenheit', s: 'A tool for measuring temperature.', how: 'Liquid in a thin tube expands as it warms, rising along a scale.', impact: 'Scientists could compare temperatures; doctors could measure fever.', f: 'Anders Celsius’s first scale put 0 at boiling and 100 at freezing — it was flipped later.', p: I('thermometer'), x: ['barometer'] },
    { id: 'newspaper', n: 'Newspaper', c: 'comm', y: 1605, d: '1605', r: 'Strasbourg', w: 'Johann Carolus', s: 'Regular printed news for anyone who could buy it.', how: 'A printing press produced copies weekly, then daily.', impact: 'News reached ordinary people; newspapers shaped politics and public opinion.', f: 'Carolus started printing his handwritten newsletter because copying it was too slow.', p: I('scroll'), x: ['printing-press', 'radio'] },
    { id: 'telescope', n: 'Telescope', c: 'science', y: 1608, d: '1608', r: 'Netherlands', w: 'Hans Lipperhey; improved by Galileo Galilei', s: 'Lenses that make distant things look closer.', how: 'A big lens gathers light and focuses it; an eyepiece magnifies the image.', impact: 'Galileo saw moons around Jupiter and craters on the Moon, changing astronomy.', f: 'Lipperhey was a spectacle-maker; his patent was refused because others had the same idea.', p: ['telescope'], x: ['microscope', ['space-atlas.html#galileo', 'Galileo in the Space Atlas']] },
    { id: 'slide-rule', n: 'Slide rule', c: 'compute', y: 1622, d: '1622', r: 'England', w: 'William Oughtred (using John Napier’s logarithms)', s: 'Two sliding scales that multiply and divide by adding lengths.', how: 'Logarithmic scales turn multiplication into adding distances.', impact: 'Engineers used slide rules for 350 years, including for the Apollo missions.', f: 'Electronic calculators replaced them almost overnight in the 1970s.', p: I('sliderule'), x: ['pascaline', 'computer'] },
    { id: 'pascaline', n: 'Mechanical calculator', c: 'compute', y: 1642, d: '1642', r: 'France', w: 'Blaise Pascal', s: 'A box of gears that could add and subtract numbers by turning dials.', how: 'When one wheel passes 9, it turns the next wheel by one — carrying the 1.', impact: 'Leibniz built one that could multiply (1673). Mechanical calculators were used until the 1970s.', f: 'Pascal made it at 19 to help his father, a tax collector.', p: I('pascaline'), x: ['abacus', 'analytical-engine'] },
    { id: 'barometer', n: 'Barometer', c: 'science', y: 1643, d: '1643', r: 'Florence, Italy', w: 'Evangelista Torricelli', s: 'A tube of mercury that measures air pressure.', how: 'Air pressure holds up a column of mercury about 76 cm tall; it moves as pressure changes.', impact: 'Falling pressure warns of storms — the start of weather forecasting.', f: 'Torricelli created the first lasting vacuum at the top of the tube.', p: I('barometer'), x: ['thermometer'] },
    { id: 'pendulum-clock', n: 'Pendulum clock', c: 'science', y: 1656, d: '1656', r: 'Netherlands', w: 'Christiaan Huygens', s: 'A clock regulated by a swinging pendulum, accurate to about a minute a day.', how: 'A pendulum of a set length always swings at the same rate.', impact: 'The most accurate clocks for nearly 300 years; Harrison’s marine chronometer (1761) then solved longitude at sea.', f: 'Galileo noticed pendulums keep steady time by watching a lamp swing in a cathedral.', p: I('pendulum'), x: ['mechanical-clock', 'quartz-atomic'] },
    { id: 'seed-drill', n: 'Seed drill', c: 'farm', y: 1701, d: '1701', r: 'England (earlier in China)', w: 'Jethro Tull', s: 'A machine that plants seeds in neat rows at the right depth.', how: 'Seeds drop through tubes into furrows cut by the drill, then are covered.', impact: 'Less seed wasted and bigger harvests, part of the British Agricultural Revolution.', f: 'Chinese farmers used multi-tube seed drills about 2,000 years earlier.', p: I('seeddrill'), x: ['plough', 'reaper'] },
    { id: 'steam-engine', n: 'Steam engine', c: 'energy', y: 1712, d: '1712; Watt’s engine 1769', r: 'England and Scotland', w: 'Thomas Newcomen; James Watt', s: 'An engine that turns the power of steam into motion.', how: 'Steam pushes a piston; Watt’s separate condenser made engines about four times more efficient.', impact: 'It powered factories, mines, trains and ships — the heart of the Industrial Revolution.', f: 'The unit of power, the watt, is named after James Watt.', p: I('steam'), x: ['locomotive', 'waterwheel'] },
    { id: 'flying-shuttle', n: 'Flying shuttle', c: 'tools', y: 1733, d: '1733', r: 'England', w: 'John Kay', s: 'A shuttle knocked across the loom by a cord, so one weaver could make wide cloth fast.', how: 'Pulling a cord sent the shuttle with the thread flying between the threads of the loom.', impact: 'Weaving became much faster — and then spinners could not keep up.', f: 'Angry weavers who feared losing work attacked Kay’s house.', p: I('loom'), x: ['spinning-jenny', 'jacquard-loom'] },
    { id: 'lightning-rod', n: 'Lightning rod', c: 'home', y: 1752, d: '1752', r: 'Philadelphia, USA', w: 'Benjamin Franklin', s: 'A metal rod on top of a building that leads lightning safely into the ground.', how: 'Lightning takes the easiest path — the metal rod and wire — instead of through the building.', impact: 'It saved many churches, ships and houses from fire.', f: 'Franklin’s famous kite experiment showed that lightning is electricity.', p: E('⚡'), x: ['battery'] },
    // ---------------- Industrial Revolution
    { id: 'spinning-jenny', n: 'Spinning jenny', c: 'tools', y: 1764, d: '1764', r: 'England', w: 'James Hargreaves', s: 'A machine that spun eight or more threads at once.', how: 'One wheel turned many spindles while a moving bar drew out the fibres.', impact: 'With Arkwright’s water frame (1769), cotton spinning moved into factories.', f: 'Jenny may have been a nickname for “engine”.', p: I('spinning'), x: ['spinning-wheel', 'flying-shuttle', 'cotton-gin'] },
    { id: 'cotton-gin', n: 'Cotton gin', c: 'farm', y: 1793, d: '1793', r: 'Georgia, USA', w: 'Eli Whitney', s: 'A machine that pulled cotton fibres away from the seeds far faster than by hand.', how: 'Wire teeth on a turning drum pulled fibres through slots too narrow for the seeds.', impact: 'Cotton became hugely profitable — and tragically, slavery in the American South expanded.', f: 'The number of enslaved people in the USA grew from about 700,000 in 1790 to nearly 4 million in 1860.', p: I('cottongin'), x: ['spinning-jenny'] },
    { id: 'battery', n: 'Battery', c: 'energy', y: 1800, d: '1800', r: 'Italy', w: 'Alessandro Volta', s: 'A pile of zinc and copper discs with salty cardboard between them — the first steady source of electricity.', how: 'Chemical reactions between two different metals push electrons through a wire.', impact: 'Electricity could finally be studied, leading to motors, the telegraph and electric light.', f: 'The volt is named after Volta.', p: I('pile'), x: ['electric-motor', 'lithium-battery'] },
    { id: 'jacquard-loom', n: 'Jacquard loom', c: 'compute', y: 1804, d: '1804', r: 'Lyon, France', w: 'Joseph Marie Jacquard', s: 'A loom controlled by chains of punched cards that wove complex patterns automatically.', how: 'Holes in each card decided which threads were lifted for each row.', impact: 'Punched cards inspired Babbage and were used in computers until the 1970s.', f: 'A portrait of Jacquard was woven with 24,000 cards.', p: I('punch'), x: ['analytical-engine', 'flying-shuttle'] },
    { id: 'locomotive', n: 'Steam locomotive', c: 'transport', y: 1804, d: '1804; Rocket 1829', r: 'Britain', w: 'Richard Trevithick; George and Robert Stephenson', s: 'A steam engine on wheels that pulls trains along rails.', how: 'Steam pushes pistons that turn the wheels.', impact: 'Railways cut journey times from days to hours and moved goods cheaply.', f: 'Stephenson’s Rocket won the Rainhill Trials in 1829 at about 46 km/h.', p: I('train'), x: ['steam-engine', 'car'] },
    { id: 'canned-food', n: 'Canned food', c: 'farm', y: 1810, d: '1810', r: 'France and England', w: 'Nicolas Appert; Peter Durand (tin can)', s: 'Food sealed in jars or tins and heated so it keeps for years.', how: 'Heat kills germs; the sealed can stops new ones getting in.', impact: 'Armies, sailors and explorers could carry food for long journeys.', f: 'The can opener was invented about 50 years after the can — people used hammers and chisels.', p: I('can'), x: ['pasteurisation', 'refrigerator'] },
    { id: 'bicycle', n: 'Bicycle', c: 'transport', y: 1817, d: '1817; safety bicycle 1885', r: 'Germany, then England', w: 'Karl Drais; John Kemp Starley', s: 'A two-wheeled machine pushed by the rider’s legs — at first without pedals.', how: 'Pedals turn a chain and gears, driving the back wheel.', impact: 'Cheap, fast personal transport; it gave women new freedom in the 1890s.', f: 'Susan B. Anthony said the bicycle did “more to emancipate women than anything else”.', p: I('bicycle'), x: ['chariot-wheel', 'car'] },
    { id: 'electric-motor', n: 'Electric motor', c: 'energy', y: 1821, d: '1821; practical motor 1834', r: 'England, then USA', w: 'Michael Faraday; Thomas Davenport', s: 'A machine that turns electricity into motion.', how: 'Electric current in a coil makes a magnetic field that pushes against magnets, spinning a shaft.', impact: 'Motors run fans, lifts, trains, washing machines and electric cars.', f: 'Faraday also discovered how to make electricity from motion (the dynamo) in 1831.', p: I('motor'), x: ['battery', 'ac-power'] },
    { id: 'photography', n: 'Photography', c: 'comm', y: 1826, d: '1826', r: 'France', w: 'Nicéphore Niépce; Louis Daguerre; William Henry Fox Talbot', s: 'Capturing an image with light on a chemically treated plate or paper.', how: 'Light changes light-sensitive chemicals, which are then fixed so the image stays.', impact: 'Photos recorded history, people and places; later came film and digital cameras.', f: 'Niépce’s first photo needed several hours, maybe days, of exposure.', p: I('camera'), x: ['motion-pictures', 'digital-camera'] },
    { id: 'matches', n: 'Friction match', c: 'home', y: 1826, d: '1826', r: 'England', w: 'John Walker', s: 'A small stick with a chemical tip that lights when struck.', how: 'Friction heats the chemicals enough to start burning.', impact: 'Lighting fires became quick and easy. Safety matches (1844) only light on the box.', f: 'Walker did not patent his invention.', p: I('match'), x: ['fire'] },
    { id: 'reaper', n: 'Mechanical reaper', c: 'farm', y: 1831, d: '1831', r: 'Virginia, USA', w: 'Cyrus McCormick (with Jo Anderson, an enslaved worker)', s: 'A horse-drawn machine that cut grain several times faster than by hand.', how: 'A moving blade cut the stalks while a reel pushed them onto a platform.', impact: 'Fewer farm workers were needed, freeing people to move to cities.', f: 'Combine harvesters today cut, thresh and clean grain in one go.', p: I('reaper'), x: ['seed-drill', 'tractor'] },
    { id: 'refrigerator', n: 'Refrigeration', c: 'home', y: 1834, d: '1834', r: 'England, later Germany and USA', w: 'Jacob Perkins; Carl von Linde', s: 'Machines that move heat out of a box to keep food cold.', how: 'A liquid evaporates inside, absorbing heat; a compressor turns it back into liquid outside.', impact: 'Food keeps longer and can travel the world; home fridges spread from the 1920s.', f: 'Before fridges, ice was cut from frozen lakes and stored in ice houses.', p: I('fridge'), x: ['canned-food', 'air-conditioning'] },
    { id: 'telegraph', n: 'Electric telegraph', c: 'comm', y: 1837, d: '1837', r: 'England and USA', w: 'William Cooke and Charles Wheatstone; Samuel Morse and Alfred Vail', s: 'Messages sent along wires as pulses of electricity.', how: 'Switching a current on and off sent dots and dashes (Morse code) to a receiver.', impact: 'News crossed continents in minutes. An undersea cable linked Europe and America in 1858.', f: 'Morse’s first public message was “What hath God wrought”.', p: I('telegraph'), x: ['telephone', 'radio'] },
    { id: 'analytical-engine', n: 'Analytical Engine', c: 'compute', y: 1837, d: '1837 (designed)', r: 'England', w: 'Charles Babbage and Ada Lovelace', s: 'A design for a steam-powered mechanical computer with memory and a processor, programmed with punched cards.', how: 'It had a “store” (memory) and a “mill” (processor), like computers today.', impact: 'Never built, but Lovelace wrote what is often called the first computer program.', f: 'Lovelace predicted computers might one day compose music.', p: I('gear'), x: ['jacquard-loom', 'computer'] },
    { id: 'rubber', n: 'Vulcanised rubber', c: 'material', y: 1839, d: '1839', r: 'USA', w: 'Charles Goodyear (rubber first used by Olmec and Maya peoples)', s: 'Rubber heated with sulfur so it stays strong and stretchy, not sticky or brittle.', how: 'Sulfur links the rubber molecules together.', impact: 'Tyres, hoses, shoes, seals and balls.', f: 'Mesoamerican peoples made rubber balls for their ball game 3,000 years earlier.', p: E('🛞'), x: ['car'] },
    { id: 'sewing-machine', n: 'Sewing machine', c: 'tools', y: 1846, d: '1846', r: 'USA', w: 'Elias Howe; Isaac Singer', s: 'A machine that stitches cloth many times faster than by hand.', how: 'A needle with the eye at the point and a shuttle below lock two threads together.', impact: 'Clothes became cheaper; ready-made clothing spread.', f: 'Howe said the idea for the needle came from a dream.', p: I('sewing'), x: ['needle'] },
    { id: 'elevator', n: 'Safety elevator', c: 'material', y: 1852, d: '1852', r: 'New York, USA', w: 'Elisha Otis', s: 'A lift with a brake that grips the shaft if the cable breaks.', how: 'If the rope goes slack, springs push catches into ratchets on the guide rails.', impact: 'Tall buildings became practical.', f: 'Otis cut the rope of his own lift at a fair in 1854 to show it was safe.', p: I('elevator'), x: ['skyscraper'] },
    { id: 'bessemer-steel', n: 'Bessemer steel', c: 'material', y: 1856, d: '1856', r: 'England', w: 'Henry Bessemer (and William Kelly in the USA)', s: 'Blowing air through molten iron to burn out extra carbon, making cheap steel in minutes.', how: 'Oxygen in the air burns away carbon and impurities, heating the metal further.', impact: 'Steel rails, bridges, ships and skyscrapers.', f: 'Steel prices fell by about 80% in a few years.', p: I('bessemer'), x: ['iron', 'skyscraper'] },
    { id: 'pasteurisation', n: 'Pasteurisation', c: 'farm', y: 1864, d: '1864', r: 'France', w: 'Louis Pasteur', s: 'Heating milk, wine or juice just enough to kill harmful germs.', how: 'Gentle heat kills most microbes without boiling the drink.', impact: 'Milk became much safer, preventing tuberculosis and other infections.', f: 'Pasteur first used it to stop wine going sour.', p: E('🥛'), x: ['canned-food', ['medicine-atlas.html#germ-theory', 'Germ theory']] },
    { id: 'dynamite', n: 'Dynamite', c: 'material', y: 1867, d: '1867', r: 'Sweden', w: 'Alfred Nobel', s: 'A safer explosive for mining and building.', how: 'Nitroglycerin was soaked into absorbent earth to make it stable until detonated.', impact: 'Tunnels, canals, railways and mines; Nobel left his fortune to create the Nobel Prizes.', f: 'Nobel read his own obituary by mistake and wanted to be remembered for something better.', p: E('🧨'), x: ['gunpowder', ['weapons-atlas.html#dynamite', 'Dynamite in the Weapons Atlas']] },
    { id: 'typewriter', n: 'Typewriter', c: 'comm', y: 1868, d: '1868', r: 'USA', w: 'Christopher Latham Sholes', s: 'A machine that printed letters onto paper when keys were pressed.', how: 'Each key swung a metal letter against an inked ribbon.', impact: 'Office work grew and many women found paid jobs as typists. Its QWERTY layout is still on keyboards.', f: 'QWERTY may have been designed to stop the metal arms jamming.', p: I('typewriter'), x: ['computer'] },
    // ---------------- age of electricity
    { id: 'telephone', n: 'Telephone', c: 'comm', y: 1876, d: '1876', r: 'USA', w: 'Alexander Graham Bell (also Elisha Gray and Antonio Meucci)', s: 'A device that sends the human voice along a wire.', how: 'Sound vibrates a thin plate, changing an electric current that recreates the sound at the other end.', impact: 'People could talk across cities, then continents.', f: 'Bell’s first words on the phone were “Mr Watson, come here, I want to see you.”', p: I('phone'), x: ['telegraph', 'mobile-phone'] },
    { id: 'phonograph', n: 'Phonograph', c: 'comm', y: 1877, d: '1877', r: 'USA', w: 'Thomas Edison', s: 'The first machine that could record sound and play it back.', how: 'A needle cut grooves in tin foil as sound vibrated it; tracing the grooves played the sound.', impact: 'Recorded music became an industry.', f: 'Edison’s first recording was “Mary had a little lamb”.', p: I('phonograph'), x: ['radio'] },
    { id: 'light-bulb', n: 'Electric light bulb', c: 'energy', y: 1879, d: '1879', r: 'England and USA', w: 'Joseph Swan; Thomas Edison; Lewis Latimer (carbon filament)', s: 'A thin glowing filament inside a glass bulb with no air.', how: 'Current heats the filament until it glows; with no oxygen it does not burn up.', impact: 'Homes, streets and factories lit at night, and demand for power grids.', f: 'LED bulbs use about 85% less energy than old filament bulbs.', p: I('bulb'), x: ['power-station', 'led'] },
    { id: 'power-station', n: 'Power station and grid', c: 'energy', y: 1882, d: '1882', r: 'London and New York', w: 'Thomas Edison', s: 'Central stations that make electricity and send it to many buildings through wires.', how: 'Steam engines turned generators; cables carried the power to customers.', impact: 'Electricity became something you could buy, like water or gas.', f: 'Edison’s Pearl Street station first powered about 400 lamps.', p: I('grid'), x: ['ac-power', 'light-bulb'] },
    { id: 'car', n: 'Motor car', c: 'transport', y: 1885, d: '1885', r: 'Germany', w: 'Karl Benz (and Bertha Benz); Gottlieb Daimler', s: 'A carriage powered by a petrol engine.', how: 'Small explosions of fuel and air push pistons that turn the wheels.', impact: 'Cars changed cities, travel and work — and are a big source of pollution.', f: 'Bertha Benz made the first long car trip in 1888, fixing it with a hairpin and a garter.', p: I('oldcar'), x: ['assembly-line', 'electric-car'] },
    { id: 'skyscraper', n: 'Skyscraper', c: 'material', y: 1885, d: '1885', r: 'Chicago, USA', w: 'William Le Baron Jenney', s: 'A tall building held up by a steel frame instead of thick walls.', how: 'A steel skeleton carries the weight; walls just hang on the frame like curtains.', impact: 'Cities could grow upward. The Burj Khalifa is 828 metres tall.', f: 'The first skyscraper, the Home Insurance Building, had just 10 floors.', p: I('skyscraper'), x: ['elevator', 'bessemer-steel'] },
    { id: 'ac-power', n: 'Alternating current (AC)', c: 'energy', y: 1888, d: '1888', r: 'USA', w: 'Nikola Tesla; George Westinghouse', s: 'Electricity that changes direction many times a second, which can be carried long distances.', how: 'Transformers raise the voltage for long cables and lower it again for homes.', impact: 'AC won the “war of the currents” and powers almost every grid today.', f: 'Tesla also invented a radio-controlled boat in 1898.', p: I('ac'), x: ['power-station', 'electric-motor'] },
    { id: 'motion-pictures', n: 'Motion pictures', c: 'comm', y: 1895, d: '1895', r: 'France', w: 'Auguste and Louis Lumière (also Edison’s Kinetoscope)', s: 'Many photographs shown quickly one after another look like movement.', how: 'A projector shows about 16–24 frames a second; the eye blends them into motion.', impact: 'Cinema became a worldwide art and industry.', f: 'Audiences reportedly jumped when the Lumières showed a train arriving at a station.', p: I('film'), x: ['photography', 'television'] },
    { id: 'radio', n: 'Radio', c: 'comm', y: 1895, d: '1895', r: 'Italy and England', w: 'Guglielmo Marconi (building on Hertz, Tesla, Bose and others)', s: 'Messages, and later voices and music, sent through the air with radio waves.', how: 'A transmitter makes electric waves; an antenna and receiver turn them back into sound.', impact: 'Ships could call for help; broadcasting reached homes from the 1920s.', f: 'Radio calls from the Titanic in 1912 brought rescue ships for the survivors.', p: I('radio'), x: ['telegraph', 'television'] },
    { id: 'air-conditioning', n: 'Air conditioning', c: 'home', y: 1902, d: '1902', r: 'New York, USA', w: 'Willis Carrier', s: 'Machines that cool air and take moisture out of it.', how: 'Like a fridge for a room: a refrigerant absorbs heat inside and releases it outside.', impact: 'Hot cities grew fast; computers and hospitals depend on it.', f: 'Carrier invented it to stop paper swelling in a printing works.', p: I('ac'), x: ['refrigerator'] },
    { id: 'airplane', n: 'Aeroplane', c: 'transport', y: 1903, d: '1903', r: 'Kitty Hawk, USA', w: 'Wilbur and Orville Wright', s: 'The first powered, controlled flight of a heavier-than-air machine.', how: 'Curved wings make lift; the Wrights steered by twisting the wings and a rudder.', impact: 'Air travel shrank the world; about 4 billion people fly each year.', f: 'The first flight lasted 12 seconds and covered 37 metres.', p: I('airplane'), x: ['jet-engine', ['space-atlas.html#goddard-rocket', 'Rockets']] },
    { id: 'plastic', n: 'Plastic (Bakelite)', c: 'material', y: 1907, d: '1907', r: 'New York, USA', w: 'Leo Baekeland', s: 'The first fully synthetic plastic, made from chemicals rather than natural materials.', how: 'Small molecules join into long chains (polymers) that can be moulded.', impact: 'Plastics are cheap and useful — and plastic waste now pollutes oceans everywhere.', f: 'Bakelite was used for early telephones, radios and jewellery.', p: I('plastic'), x: ['nylon'] },
    { id: 'haber-bosch', n: 'Haber–Bosch process (fertiliser)', c: 'farm', y: 1909, d: '1909', r: 'Germany', w: 'Fritz Haber and Carl Bosch', s: 'Making ammonia from nitrogen in the air, to produce fertiliser.', how: 'Nitrogen and hydrogen are combined at high pressure and temperature with an iron catalyst.', impact: 'Fertiliser made this way helps feed about half the world’s people.', f: 'Haber also led Germany’s poison gas programme in WWI — a dark side of the same chemist.', p: I('haber'), x: ['farming', ['weapons-atlas.html#poison-gas', 'Poison gas']] },
    { id: 'assembly-line', n: 'Moving assembly line', c: 'tools', y: 1913, d: '1913', r: 'Detroit, USA', w: 'Henry Ford', s: 'Cars moved past workers, each doing one task, instead of workers moving around a car.', how: 'A conveyor pulled each car along at a steady speed.', impact: 'Building a Model T fell from 12 hours to about 90 minutes, and cars became affordable.', f: 'Ford got the idea partly from meat-packing plants.', p: I('car', { color: '#2d3741' }), x: ['car'] },
    { id: 'zipper', n: 'Zip fastener', c: 'home', y: 1913, d: '1913', r: 'USA', w: 'Gideon Sundback', s: 'Two rows of interlocking teeth joined by a sliding fastener.', how: 'The slider pushes the teeth together so they lock, or wedges them apart.', impact: 'Used on clothes, bags and tents everywhere.', f: 'It got the name “zipper” from a brand of rubber boots in 1923.', p: I('zip'), x: ['sewing-machine'] },
    { id: 'tractor', n: 'Petrol tractor', c: 'farm', y: 1917, d: '1917', r: 'USA', w: 'Henry Ford (Fordson); earlier John Froelich (1892)', s: 'Small, affordable tractors that replaced horses on farms.', how: 'A petrol engine drives the wheels and powers ploughs and other tools.', impact: 'One farmer could work far more land; farm work fell sharply.', f: 'Millions of farm horses were replaced within a few decades.', p: E('🚜'), x: ['plough', 'reaper'] },
    { id: 'television', n: 'Television', c: 'comm', y: 1926, d: '1926–1927', r: 'Scotland and USA', w: 'John Logie Baird; Philo Farnsworth', s: 'Moving pictures sent through the air and shown on a screen at home.', how: 'A camera turns the image into electrical signals line by line; the TV rebuilds the picture.', impact: 'TV became the main source of news and entertainment for decades.', f: 'Farnsworth said he got the idea of scanning lines while ploughing a field.', p: I('tv'), x: ['radio', 'motion-pictures'] },
    { id: 'nylon', n: 'Nylon', c: 'material', y: 1935, d: '1935', r: 'Delaware, USA', w: 'Wallace Carothers at DuPont', s: 'The first fully synthetic fibre — strong, light and stretchy.', how: 'Two chemicals join into long polymer chains that can be pulled into threads.', impact: 'Stockings, parachutes, ropes, toothbrushes and clothes.', f: 'When nylon stockings went on sale in 1940, 4 million pairs sold in days.', p: I('nylon'), x: ['plastic'] },
    { id: 'jet-engine', n: 'Jet engine', c: 'transport', y: 1937, d: '1937', r: 'England and Germany', w: 'Frank Whittle; Hans von Ohain', s: 'An engine that sucks in air, compresses it, burns fuel in it and blasts it out of the back.', how: 'A turbine spun by the hot gas also drives the compressor at the front.', impact: 'Jets made air travel fast and cheap.', f: 'Whittle and von Ohain worked separately and only met after the war.', p: I('jet'), x: ['airplane', ['weapons-atlas.html#jet-fighter', 'The first jet fighters']] },
    { id: 'photocopier', n: 'Photocopier', c: 'comm', y: 1938, d: '1938', r: 'New York, USA', w: 'Chester Carlson', s: 'A machine that copies documents using light and static electricity (xerography).', how: 'Light makes a charged drum lose charge where the page is white; toner sticks to the rest and is melted onto paper.', impact: 'Offices could copy anything in seconds.', f: 'Over 20 companies turned Carlson down before Xerox agreed.', p: E('📠'), x: ['printing-press'] },
    { id: 'ballpoint-pen', n: 'Ballpoint pen', c: 'home', y: 1938, d: '1938', r: 'Hungary and Argentina', w: 'László Bíró and György Bíró', s: 'A pen with a tiny rolling ball at the tip that spreads quick-drying ink.', how: 'The ball rolls, picking up ink from inside and spreading it on paper.', impact: 'Cheap, clean writing for everyone.', f: 'In Argentina and other countries, a ballpoint pen is still called a “birome” or “biro”.', p: E('🖊️'), x: ['typewriter'] },
    { id: 'computer', n: 'First programmable computers', c: 'compute', y: 1941, d: '1941–1945', r: 'Germany, UK and USA', w: 'Konrad Zuse (Z3); Tommy Flowers (Colossus); J. Presper Eckert and John Mauchly (ENIAC)', s: 'Machines that could be programmed to do different calculations automatically.', how: 'Relays or vacuum tubes switched on and off to represent the 1s and 0s of binary numbers.', impact: 'Colossus helped break German codes; ENIAC calculated artillery tables.', f: 'ENIAC weighed 27 tonnes; its first programmers were six women.', p: I('eniac'), x: ['analytical-engine', 'transistor'] },
    // ---------------- electronic age
    { id: 'microwave-oven', n: 'Microwave oven', c: 'home', y: 1946, d: '1946', r: 'USA', w: 'Percy Spencer', s: 'An oven that heats food quickly with microwaves.', how: 'Microwaves make water molecules in food jiggle, which heats it.', impact: 'Fast cooking and reheating in homes and offices.', f: 'Spencer noticed a chocolate bar melting in his pocket while working near radar equipment.', p: I('microwave'), x: [['weapons-atlas.html#radar', 'Radar']] },
    { id: 'transistor', n: 'Transistor', c: 'compute', y: 1947, d: '1947', r: 'New Jersey, USA', w: 'John Bardeen, Walter Brattain and William Shockley', s: 'A tiny switch with no moving parts that controls electric current — the building block of electronics.', how: 'A small current at one connection controls a larger current through a semiconductor.', impact: 'Radios, computers and phones became small, cheap and reliable.', f: 'A modern chip can hold over 100 billion transistors.', p: I('transistor'), x: ['integrated-circuit', 'computer'] },
    { id: 'credit-card', n: 'Credit card', c: 'home', y: 1950, d: '1950', r: 'New York, USA', w: 'Frank McNamara (Diners Club)', s: 'A card that lets you buy now and pay later.', how: 'The card company pays the shop and sends the customer a bill.', impact: 'Cards, then chips and contactless payments, are replacing cash.', f: 'McNamara had the idea after forgetting his wallet at a restaurant.', p: I('card'), x: ['paper-money', 'atm'] },
    { id: 'nuclear-power', n: 'Nuclear power station', c: 'energy', y: 1954, d: '1954', r: 'Obninsk, Soviet Union', w: 'Soviet scientists', s: 'A power station that makes electricity from heat released by splitting atoms.', how: 'Controlled chain reactions in uranium fuel heat water to steam that spins turbines.', impact: 'Produces about 10% of world electricity with little carbon; accidents like Chernobyl (1986) raised fears.', f: 'One uranium fuel pellet the size of a fingertip holds as much energy as a tonne of coal.', p: I('nuclear'), x: ['solar-cell', ['weapons-atlas.html#atomic-bomb', 'The atomic bomb']] },
    { id: 'solar-cell', n: 'Solar cell', c: 'energy', y: 1954, d: '1954', r: 'New Jersey, USA', w: 'Daryl Chapin, Calvin Fuller and Gerald Pearson (Bell Labs)', s: 'A thin silicon panel that turns sunlight directly into electricity.', how: 'Light knocks electrons loose in silicon, and the cell’s layers push them into a circuit.', impact: 'Solar power is now the cheapest electricity in many places.', f: 'Solar cells first powered a satellite, Vanguard 1, in 1958.', p: I('solar'), x: ['nuclear-power', 'windmill', ['space-atlas.html#vanguard-1', 'Vanguard 1']] },
    { id: 'velcro', n: 'Velcro', c: 'home', y: 1955, d: '1955', r: 'Switzerland', w: 'George de Mestral', s: 'Two strips — one with tiny hooks, one with loops — that stick together.', how: 'Thousands of hooks catch in the loops; pulling hard frees them.', impact: 'Shoes, clothes, bags and even spacesuits.', f: 'De Mestral got the idea from burrs stuck to his dog’s fur after a walk.', p: E('🧷'), x: ['zipper'] },
    { id: 'container-ship', n: 'Shipping container', c: 'transport', y: 1956, d: '1956', r: 'USA', w: 'Malcolm McLean', s: 'Standard steel boxes that move between ships, trains and trucks without unpacking.', how: 'Every container is the same size, so cranes, ships and trucks all fit it.', impact: 'Shipping became so cheap that global trade exploded.', f: 'Loading costs fell by about 95%.', p: I('container'), x: ['sailboat'] },
    { id: 'integrated-circuit', n: 'Integrated circuit (microchip)', c: 'compute', y: 1958, d: '1958–1959', r: 'USA', w: 'Jack Kilby; Robert Noyce', s: 'Many transistors and connections made together on one small piece of silicon.', how: 'Patterns are printed onto silicon with light and chemicals, layer by layer.', impact: 'The number of transistors on chips doubled about every two years (Moore’s law).', f: 'Kilby’s first chip was about the size of a paperclip.', p: I('chip'), x: ['transistor', 'microprocessor'] },
    { id: 'laser', n: 'Laser', c: 'science', y: 1960, d: '1960', r: 'California, USA', w: 'Theodore Maiman', s: 'A device that makes a narrow, intense beam of light of one colour.', how: 'Atoms are “pumped” with energy and release light in step; mirrors build it into a beam.', impact: 'Barcode scanners, eye surgery, fibre-optic internet, measurement and cutting metal.', f: 'Lasers bounced off mirrors left by Apollo astronauts measure the Moon’s distance to a few centimetres.', p: I('laser'), x: [['surgery-atlas.html#laser-surgery', 'Laser surgery'], ['weapons-atlas.html#laser-weapon', 'Laser weapons']] },
    { id: 'led', n: 'LED light', c: 'energy', y: 1962, d: '1962; blue LED 1993', r: 'USA, then Japan', w: 'Nick Holonyak; Shuji Nakamura, Isamu Akasaki and Hiroshi Amano (blue)', s: 'A tiny semiconductor that glows when current flows through it.', how: 'Electrons release light as they cross between two kinds of semiconductor.', impact: 'Blue LEDs made white LED lighting possible, using far less energy. Nobel Prize 2014.', f: 'The first LEDs were red and very dim.', p: I('led'), x: ['light-bulb'] },
    { id: 'atm', n: 'Cash machine (ATM)', c: 'home', y: 1967, d: '1967', r: 'London, UK', w: 'John Shepherd-Barron', s: 'A machine that gives out cash at any time of day.', how: 'Early ones used special cheques; later, cards and a PIN number.', impact: 'Banking became possible outside opening hours.', f: 'Shepherd-Barron chose a 4-digit PIN because his wife could only remember four numbers.', p: I('atm'), x: ['credit-card'] },
    { id: 'internet', n: 'Internet', c: 'comm', y: 1969, d: '1969; TCP/IP 1983', r: 'USA', w: 'ARPANET team; Vint Cerf and Bob Kahn (TCP/IP)', s: 'A network of networks that lets computers anywhere exchange data.', how: 'Data is split into packets that travel separately and are put back together at the end.', impact: 'Email, the web, video calls and online everything.', f: 'The first message, in 1969, was meant to be “LOGIN” — it crashed after “LO”.', p: I('globe'), x: ['web', 'email'] },
    { id: 'microprocessor', n: 'Microprocessor', c: 'compute', y: 1971, d: '1971', r: 'California, USA', w: 'Federico Faggin, Ted Hoff, Stanley Mazor and Masatoshi Shima (Intel 4004)', s: 'A whole computer processor on a single chip.', how: 'One chip fetches instructions and carries them out, step by step.', impact: 'It made personal computers, phones and smart devices possible.', f: 'The Intel 4004 was designed for a Japanese calculator.', p: I('chip'), x: ['integrated-circuit', 'personal-computer'] },
    { id: 'email', n: 'Email', c: 'comm', y: 1971, d: '1971', r: 'USA', w: 'Ray Tomlinson', s: 'Messages sent from one computer user to another across a network.', how: 'Tomlinson chose the @ sign to separate the user’s name from their computer.', impact: 'Billions of emails are sent every day.', f: 'Tomlinson said he could not remember what the first email said — probably a test like “QWERTYUIOP”.', p: E('📧'), x: ['internet'] },
    { id: 'video-game', n: 'Video game', c: 'home', y: 1972, d: '1972', r: 'USA', w: 'Ralph Baer (home console); Allan Alcorn and Atari (Pong)', s: 'Games played on a screen with electronic controls.', how: 'A computer draws the game and responds to the player’s buttons.', impact: 'Video games became bigger than films and music combined.', f: 'Earlier, in 1958, Tennis for Two was played on an oscilloscope screen.', p: I('game'), x: ['personal-computer'] },
    { id: 'mobile-phone', n: 'Mobile phone', c: 'comm', y: 1973, d: '1973', r: 'New York, USA', w: 'Martin Cooper (Motorola)', s: 'A telephone you can carry, connected by radio to a network of base stations.', how: 'Each area (cell) has an antenna; calls hand over from cell to cell as you move.', impact: 'There are more mobile phone connections than people in the world.', f: 'Cooper’s first call was to a rival at Bell Labs.', p: E('📱'), x: ['telephone', 'smartphone'] },
    { id: 'barcode', n: 'Barcode', c: 'home', y: 1974, d: '1974 (first scan)', r: 'USA', w: 'Norman Woodland and Bernard Silver; George Laurer (UPC)', s: 'Stripes that a laser scanner reads to identify a product.', how: 'Black and white bars of different widths stand for digits.', impact: 'Checkouts became fast and shops could track stock.', f: 'The first item scanned was a pack of chewing gum in Ohio.', p: I('barcode'), x: ['qr-code'] },
    { id: 'digital-camera', n: 'Digital camera', c: 'comm', y: 1975, d: '1975', r: 'New York, USA', w: 'Steven Sasson (Kodak)', s: 'A camera that records pictures as numbers instead of on film.', how: 'A sensor turns light into electrical signals that are stored as pixels.', impact: 'Phones put a camera in almost every pocket.', f: 'The first one took 23 seconds to save a black-and-white photo to a cassette tape.', p: I('camera'), x: ['photography', 'smartphone'] },
    { id: 'personal-computer', n: 'Personal computer', c: 'compute', y: 1977, d: '1977', r: 'USA', w: 'Steve Wozniak and Steve Jobs (Apple II); also Commodore and Tandy', s: 'Computers small and cheap enough for homes and schools.', how: 'A microprocessor, memory, keyboard and screen in one desk-sized machine.', impact: 'Word processing, spreadsheets, games and later the internet in every home.', f: 'The Apple I (1976) was sold as a bare circuit board.', p: I('computer'), x: ['microprocessor', 'web'] },
    { id: 'gps-navigation', n: 'GPS navigation', c: 'transport', y: 1978, d: '1978 (first satellite); 1995 (complete)', r: 'USA', w: 'US Department of Defense (Bradford Parkinson, Roger Easton, Ivan Getting); Gladys West (Earth model)', s: 'Satellites that let a receiver work out exactly where it is anywhere on Earth.', how: 'The receiver times signals from at least four satellites to calculate its position.', impact: 'Maps on phones, aircraft, shipping, farming and timing for the internet.', f: 'GPS must correct for Einstein’s relativity or it would drift about 10 km a day.', p: I('pin'), x: ['compass', ['space-atlas.html#gps', 'GPS satellites']] },
    { id: '3d-printing', n: '3D printing', c: 'tools', y: 1984, d: '1984', r: 'USA', w: 'Chuck Hull', s: 'Building objects layer by layer from a computer design.', how: 'A laser hardens liquid resin, or a nozzle lays melted plastic, one thin layer at a time.', impact: 'Prototypes, medical implants, spare parts and even houses.', f: 'Hull called it stereolithography.', p: I('printer3d'), x: ['personal-computer', ['surgery-atlas.html#printed-implants', '3D-printed implants']] },
    { id: 'web', n: 'World Wide Web', c: 'comm', y: 1989, d: '1989', r: 'CERN, Switzerland', w: 'Tim Berners-Lee', s: 'Pages of information linked together and read in a browser.', how: 'Web addresses (URLs), links (HTTP) and page code (HTML) work together over the internet.', impact: 'Billions of websites — including this one.', f: 'Berners-Lee gave the web away for free.', p: I('web'), x: ['internet', 'search-engine'] },
    // ---------------- digital age
    { id: 'lithium-battery', n: 'Lithium-ion battery', c: 'energy', y: 1991, d: '1991', r: 'Japan, after work in the USA and UK', w: 'John Goodenough, Stanley Whittingham, Akira Yoshino (Sony)', s: 'A light, rechargeable battery that stores a lot of energy.', how: 'Lithium ions move between two electrodes as the battery charges and discharges.', impact: 'Phones, laptops, electric cars and storing solar power. Nobel Prize 2019.', f: 'Goodenough won the Nobel Prize at 97 — the oldest winner ever.', p: I('liion'), x: ['battery', 'electric-car'] },
    { id: 'qr-code', n: 'QR code', c: 'comm', y: 1994, d: '1994', r: 'Japan', w: 'Masahiro Hara (Denso Wave)', s: 'A square barcode that phones can read in any direction.', how: 'Three corner squares show the camera the code’s position; the dots store data, with error correction.', impact: 'Menus, tickets, payments — and MigaBuilder’s QR Forge makes them.', f: 'It was invented to track car parts in factories.', p: I('qr'), x: ['barcode', 'smartphone'] },
    { id: 'wi-fi', n: 'Wi-Fi', c: 'comm', y: 1997, d: '1997', r: 'Australia and USA', w: 'John O’Sullivan and team at CSIRO; IEEE 802.11', s: 'Wireless internet connections inside homes, offices and cafés.', how: 'Radio waves carry data between devices and a router.', impact: 'Laptops, phones and smart devices connect without cables.', f: 'Wi-Fi does not actually stand for anything.', p: E('📶'), x: ['internet', 'radio'] },
    { id: 'search-engine', n: 'Web search engine', c: 'comm', y: 1998, d: '1998', r: 'USA', w: 'Larry Page and Sergey Brin (Google); earlier Archie (1990)', s: 'Programs that find and rank web pages for any search.', how: 'Robots visit pages and build an index; ranking uses links and many other signals.', impact: 'Finding information became instant.', f: '“Google” comes from googol, the number 1 followed by 100 zeros.', p: I('web'), x: ['web'] },
    { id: 'smartphone', n: 'Smartphone', c: 'comm', y: 2007, d: '2007', r: 'USA', w: 'Apple (iPhone); earlier IBM Simon (1994)', s: 'A pocket computer with a touchscreen, internet, camera and apps.', how: 'A powerful chip, sensors, radios and a touchscreen in one device.', impact: 'Over 4 billion people use smartphones.', f: 'A smartphone has far more computing power than the computers that guided Apollo 11.', p: I('smartphone'), x: ['mobile-phone', 'lithium-battery'] },
    { id: 'electric-car', n: 'Modern electric car', c: 'transport', y: 2008, d: '2008', r: 'USA, then worldwide', w: 'Tesla (Roadster); Nissan (Leaf, 2010)', s: 'Cars powered by lithium-ion batteries and electric motors.', how: 'Batteries feed motors that drive the wheels; braking recharges the battery.', impact: 'Electric cars cut exhaust pollution and are growing fast worldwide.', f: 'Electric cars were popular in 1900, before cheap petrol and Ford’s Model T.', p: I('car', { color: '#2b5a8a' }), x: ['car', 'lithium-battery'] },
    { id: 'ai', n: 'Artificial intelligence', c: 'compute', y: 2012, d: '1956 (term); deep learning 2012; chatbots 2022', r: 'USA, UK, Canada and worldwide', w: 'John McCarthy (term); Geoffrey Hinton and students; many labs', s: 'Computer programs that learn from data to recognise images, translate, write and answer questions.', how: 'Neural networks with many layers adjust millions or billions of numbers as they learn from examples.', impact: 'AI tools now help write, code, translate, find diseases in scans and more — and raise questions about jobs, truth and safety.', f: 'In 2012 a neural network called AlexNet suddenly beat all other programs at recognising pictures.', p: I('ai'), x: ['computer', 'smartphone'] },
    { id: 'quartz-atomic', n: 'Quartz and atomic clocks', c: 'science', y: 1955, d: '1927 (quartz); 1955 (atomic)', r: 'USA and UK', w: 'Warren Marrison; Louis Essen', s: 'Clocks timed by vibrating crystals or by atoms — accurate to a second in millions of years.', how: 'Atoms of caesium absorb microwaves at an exact frequency used to define the second.', impact: 'GPS, phone networks and the internet depend on atomic time.', f: 'Since 1967, the second has been defined by caesium atoms, not Earth’s rotation.', p: I('clock'), x: ['pendulum-clock', 'gps-navigation'] }
  ];
})();
